    for i in range(R):
        for j in range(C):
            if inp[i][j]==2:
                cands=[]
                for r in range(i-5,i+6):
                    for s in range(j-5,j+6):
                        if (r,s)!=(i,j) and 0<=r<R and 0<=s<C and inp[r][s]!=2: cands.append(inp[r][s])
                if cands: cands.sort(key=x.count() if False else None)
