def solve(g):
    n=len(g)
    def nb(i,j):
        vals=[]
        for a in range(max(0,i-1),min(n-1,i+2)):
            for b in range(max(0,j-1),min(n-1,j+2)):
                if (a,b)!=(i,j): vals.append(g[a][b])
        return Counter(vals)
    h=[[g[n-1-i][j] for j in range(n)] for i in range(n)]
    o=[list(h[i]) for i in range(n)]
    for i in range(n):
        for j in range(n):
            if h[i][j]==2:
                cnt=nb(i,j)
                o[i][j]=cnt.most_common(1)[0][0] if len(cnt)>1 else None
    return o
