# Decide: rule = out = rot180(ki), with single-noise cells taking their original input value. For demo3 double-noise cells the fill comes from nearest non-2 neighbor in input within radius 3. Verify this fully on demo3, then apply to test.
def solve(k):
    n=len(k);m=len(k[0])
    R=[[k[n-1-i][m-1-j] for j in range(m)] for i in range(n)]
    res=[[R[i][j] for j in range(m)] for i in range(n)]
    nz={(i,j) for i in range(n) for j in range(m) if k[i][j]==2}
    # component-based: for each noise cell whose rot partner is also noise, use nearest non-2 original
    seen=set()
    for pt in sorted(nz):
        if pt in seen: continue
        stack=[pt]; seen.add(pt); c=[]
        while stack:
            a,b=stack.pop(); c.append((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(a+da,b+db)
                if q in nz and q not in seen: seen.add(q); stack.append(q)
        rs=min(p[0] for p in c); cs=min(p[1] for p in c)
        h=max(p[0] for p in c)-rs+1; w=max(p[1] for p in c)-cs+1
        # fill comp: for each cell, value = nearest non-2 original within radius 3
        for (a,b) in c:
            best=None
            for da in range(-3,4):
                for db in range(-3,4):
                    x,y=a+da,b+db
                    if 0<=x<n and 0<=y<m and k[x][y]!=2:
                        d=abs(da)+abs(db)
                        if best is None or d<best[0] or (d==best[0] and (x,y)<best[1]):
                            best=(d,(x,y))
            res[a][b]=k[best[1]][best[0]]
    return res
